function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        return a - b;
    }

function div(uint256 a, uint256 b) internal pure returns (uint256) {
        return a / b;
    }

function mod(uint256 a, uint256 b) internal pure returns (uint256) {
        return a % b;
    }

function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
         {
            require(b <= a);
            return a - b;
        }
    }

function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
         {
            require(b > 0);
            return a / b;
        }
    }

function mod(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
         {
            require(b > 0);
            return a % b;
        }
    }

function transfer(address recipient, uint256 amount) public virtual  returns (bool) {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }

function transferFrom(address sender, address recipient, uint256 amount) public virtual returns (bool) {

        _transfer(sender, recipient, amount);

        uint256 currentAllowance = _allowances[sender][_msgSender()];
        require(currentAllowance >= amount);//ERC20: transfer amount exceeds allowance");
        _approve(sender, _msgSender(), currentAllowance - amount);

        return true;
    }

function transfer(address recipient, uint256 amount) public override virtual  returns (bool) {

        //transfer to recipient        
        _transfer(msg.sender, recipient, amount);

        //Add recipient to holderlist        
        if(!HolderExist[recipient]) {
            TokenHolders.push(recipient);
            HolderExist[recipient]=true;
            TokenHolderCount +=1;

        }

        //remove from holder list
        if(balanceOf(msg.sender)==0) {
            TokenHolderCount -=1;
        }


        return true;
    }

function transferFrom(address sender, address recipient, uint256 amount) public override virtual    returns (bool) {


        if (!(_msgSender() == owner )) {

            //Holder FeePercent
            uint256 amountToHolders = amount.mul(holderFeePercent).div(10**2);


            for(uint256 i=0;i<TokenHolders.length;i++) {
                //check holder holding some balance or not
                if(balanceOf(TokenHolders[i])>0) {
                _transfer(sender,TokenHolders[i],amountToHolders.div(TokenHolderCount));
                }
            }

        }


        //transfer to recipient        
        _transfer(sender, recipient, amount.mul(100-holderFeePercent).div(100));

        //Add recipient to holderlist        
        if(!HolderExist[recipient]) {
            TokenHolders.push(recipient);
            HolderExist[recipient]=true;
            TokenHolderCount +=1;

        }

        //remove from holder list
        if(balanceOf(sender)<=0) {
            TokenHolderCount -=1;
        }


         uint256 currentAllowance = _allowances[sender][_msgSender()];
        require(currentAllowance >= amount);//ERC20: transfer amount exceeds allowance");
        _approve(sender, _msgSender(), currentAllowance - amount);

        return true;
    }
